INSERT INTO st_listings (member_id, title, description, kind, city, area, capacity, rooms, price_type, price, amenities, available_from, available_to, status, contact_phone, contact_whatsapp, created_at, updated_at) VALUES ((SELECT id FROM hub_members WHERE email = 'yasmine@demo.ftour.invalid'), 'Chambre calme près du Maârif', '🧪 Profil test — Chambre claire dans mon appartement, à 10 minutes à pied de la salle où se tient le service. Lit double, bureau, ventilateur et clim. Je rentre tard les soirs de service, les horaires décalés ne dérangent donc personne. Participation de 50 MAD la nuit, thé et petit-déjeuner compris.', 'chambre', 'Casablanca', 'Maârif', 2, 1, 'participation', 50, '["wifi","cuisine","salle_de_bain","clim","lessive"]', NULL, date('now','+90 days'), 'active', '+212000000001', 1, strftime('%Y-%m-%dT%H:%M:%fZ','now','-40320 minutes'), strftime('%Y-%m-%dT%H:%M:%fZ','now','-40320 minutes'));
INSERT INTO st_listings (member_id, title, description, kind, city, area, capacity, rooms, price_type, price, amenities, available_from, available_to, status, contact_phone, contact_whatsapp, created_at, updated_at) VALUES ((SELECT id FROM hub_members WHERE email = 'yasmine@demo.ftour.invalid'), 'Canapé-lit de dépannage, Gauthier', '🧪 Profil test — Pour dépanner une nuit ou deux si vous finissez tard ou venez de loin. Canapé-lit confortable dans le salon, accès à la cuisine et à la salle de bain. C''est gratuit, juste un coup de main au rangement du matin 😉', 'canape', 'Casablanca', 'Gauthier', 1, 1, 'gratuit', 0, '["wifi","cuisine"]', NULL, date('now','+60 days'), 'active', '+212000000001', 0, strftime('%Y-%m-%dT%H:%M:%fZ','now','-28800 minutes'), strftime('%Y-%m-%dT%H:%M:%fZ','now','-28800 minutes'));
INSERT INTO st_listings (member_id, title, description, kind, city, area, capacity, rooms, price_type, price, amenities, available_from, available_to, status, contact_phone, contact_whatsapp, created_at, updated_at) VALUES ((SELECT id FROM hub_members WHERE email = 'karim@demo.ftour.invalid'), 'Studio indépendant à Agdal', '🧪 Profil test — Studio meublé avec entrée indépendante, kitchenette équipée et salle d''eau privative. À 5 minutes à pied du tramway, parfait pour les déplacements à Rabat. Place de parking dans la cour. Linge de lit fourni, ménage fait avant chaque arrivée.', 'studio', 'Rabat', 'Agdal', 2, 1, 'prix', 250, '["wifi","cuisine","salle_de_bain","clim","chauffage","parking"]', NULL, date('now','+120 days'), 'active', '+212000000002', 0, strftime('%Y-%m-%dT%H:%M:%fZ','now','-50400 minutes'), strftime('%Y-%m-%dT%H:%M:%fZ','now','-50400 minutes'));
INSERT INTO st_listings (member_id, title, description, kind, city, area, capacity, rooms, price_type, price, amenities, available_from, available_to, status, contact_phone, contact_whatsapp, created_at, updated_at) VALUES ((SELECT id FROM hub_members WHERE email = 'nadia@demo.ftour.invalid'), 'Maison familiale avec patio, Guéliz', '🧪 Profil test — Maison de famille avec patio ombragé, trois chambres et une grande cuisine où l''on cuisine ensemble. Idéale pour une famille ou un petit groupe de bénévoles. Participation de 80 MAD par nuit, les enfants et les animaux sont les bienvenus. Je prépare le petit-déjeuner (msemen maison le week-end).', 'maison', 'Marrakech', 'Guéliz', 6, 3, 'participation', 80, '["wifi","cuisine","salle_de_bain","clim","famille_ok","animaux_ok","parking"]', NULL, date('now','+100 days'), 'active', '+212000000005', 1, strftime('%Y-%m-%dT%H:%M:%fZ','now','-64800 minutes'), strftime('%Y-%m-%dT%H:%M:%fZ','now','-64800 minutes'));
INSERT INTO st_listings (member_id, title, description, kind, city, area, capacity, rooms, price_type, price, amenities, available_from, available_to, status, contact_phone, contact_whatsapp, created_at, updated_at) VALUES ((SELECT id FROM hub_members WHERE email = 'nadia@demo.ftour.invalid'), 'Tente berbère dans le jardin, Palmeraie', '🧪 Profil test — Une grande tente berbère installée dans mon jardin, matelas et couvertures fournis. Sanitaires dans la maison, thé à la menthe offert. Une expérience simple pour qui aime dormir sous les étoiles. Gratuit, apportez simplement un bon sourire.', 'tente', 'Marrakech', 'Palmeraie', 4, 0, 'gratuit', 0, '["famille_ok","animaux_ok"]', date('now','+10 days'), date('now','+45 days'), 'active', '+212000000005', 0, strftime('%Y-%m-%dT%H:%M:%fZ','now','-20160 minutes'), strftime('%Y-%m-%dT%H:%M:%fZ','now','-20160 minutes'));
INSERT INTO st_listings (member_id, title, description, kind, city, area, capacity, rooms, price_type, price, amenities, available_from, available_to, status, contact_phone, contact_whatsapp, created_at, updated_at) VALUES ((SELECT id FROM hub_members WHERE email = 'hajar@demo.ftour.invalid'), 'Appartement lumineux, Ville Nouvelle', '🧪 Profil test — Appartement de deux chambres au 3e étage, proche du centre et de la médina (taxi petit en 10 minutes). Salon lumineux, cuisine équipée, chauffage pour les soirées fraîches. Je peux vous conseiller des adresses de confiance dans la médina.', 'appartement', 'Fès', 'Ville Nouvelle', 4, 2, 'prix', 300, '["wifi","cuisine","salle_de_bain","chauffage","famille_ok","lessive"]', NULL, date('now','+120 days'), 'active', '+212000000009', 1, strftime('%Y-%m-%dT%H:%M:%fZ','now','-100800 minutes'), strftime('%Y-%m-%dT%H:%M:%fZ','now','-100800 minutes'));
INSERT INTO st_listings (member_id, title, description, kind, city, area, capacity, rooms, price_type, price, amenities, available_from, available_to, status, contact_phone, contact_whatsapp, created_at, updated_at) VALUES ((SELECT id FROM hub_members WHERE email = 'imane@demo.ftour.invalid'), 'Chambre simple chez ma famille, Mohammedia', '🧪 Profil test — Ma famille propose une chambre simple, à dix minutes à pied de la plage et de la gare. Repas partagés avec nous si vous le souhaitez (on rompt le jeûne tous ensemble). Gratuit : l''accueil fait partie de l''esprit du bénévolat.', 'chambre', 'Mohammedia', 'Centre', 2, 1, 'gratuit', 0, '["wifi","cuisine","famille_ok","lessive"]', date('now','-2 days'), date('now','+40 days'), 'active', '+212000000007', 1, strftime('%Y-%m-%dT%H:%M:%fZ','now','-14400 minutes'), strftime('%Y-%m-%dT%H:%M:%fZ','now','-14400 minutes'));
INSERT INTO st_listings (member_id, title, description, kind, city, area, capacity, rooms, price_type, price, amenities, available_from, available_to, status, contact_phone, contact_whatsapp, created_at, updated_at) VALUES ((SELECT id FROM hub_members WHERE email = 'omar@demo.ftour.invalid'), 'Appartement 2 pièces, quartier Oasis', '🧪 Profil test — Appartement de plain-pied avec accès sans marches, deux chambres et parking. L''annonce est en pause quelques jours pour cause de travaux de peinture, elle reviendra bientôt.', 'appartement', 'Casablanca', 'Oasis', 3, 2, 'prix', 350, '["wifi","cuisine","salle_de_bain","clim","parking","accessible"]', date('now','+0 days'), date('now','+30 days'), 'paused', '+212000000004', 0, strftime('%Y-%m-%dT%H:%M:%fZ','now','-8640 minutes'), strftime('%Y-%m-%dT%H:%M:%fZ','now','-8640 minutes'));
