INSERT INTO pro_jobs (member_id, title, company, city, type, description, contact, status, created_at, updated_at) VALUES ((SELECT id FROM hub_members WHERE email = 'salma@demo.ftour.invalid'), 'Animateur(trice) bénévole, ateliers jeunes', 'Association Exemple (fictive)', 'Casablanca', 'benevolat', '🧪 Profil test — Nous cherchons des animateurs pour des ateliers de soutien scolaire et de loisirs créatifs, un à deux après-midis par semaine. Aucune expérience exigée, un entretien d''accueil de 30 minutes suffit. Idéal pour un étudiant ou un lycéen motivé.', '+212000000003', 'open', strftime('%Y-%m-%dT%H:%M:%fZ','now','-4320 minutes'), strftime('%Y-%m-%dT%H:%M:%fZ','now','-4320 minutes'));
INSERT INTO pro_jobs (member_id, title, company, city, type, description, contact, status, created_at, updated_at) VALUES ((SELECT id FROM hub_members WHERE email = 'hajar@demo.ftour.invalid'), 'Stage RH, 4 mois', 'Groupe Exemple Fès (fictif)', 'Fès', 'stage', '🧪 Profil test — Stage en ressources humaines : planification des équipes, suivi des absences, accueil des nouveaux collaborateurs. Vous seconderez la responsable RH sur des missions concrètes. Niveau bac+3 minimum, bon relationnel et maîtrise d''Excel demandés.', '+212000000009', 'open', strftime('%Y-%m-%dT%H:%M:%fZ','now','-3600 minutes'), strftime('%Y-%m-%dT%H:%M:%fZ','now','-3600 minutes'));
INSERT INTO pro_jobs (member_id, title, company, city, type, description, contact, status, created_at, updated_at) VALUES ((SELECT id FROM hub_members WHERE email = 'nadia@demo.ftour.invalid'), 'Commis de pâtisserie', 'Pâtisserie Exemple (fictive)', 'Marrakech', 'cdi', '🧪 Profil test — Notre atelier de pâtisserie marocaine recrute un commis pour la préparation des gâteaux et la mise en boîte des commandes. Horaires du matin, du mardi au samedi. Formation en interne, nous cherchons surtout quelqu''un de soigneux et ponctuel.', '+212000000005', 'open', strftime('%Y-%m-%dT%H:%M:%fZ','now','-3240 minutes'), strftime('%Y-%m-%dT%H:%M:%fZ','now','-3240 minutes'));
INSERT INTO pro_jobs (member_id, title, company, city, type, description, contact, status, created_at, updated_at) VALUES ((SELECT id FROM hub_members WHERE email = 'omar@demo.ftour.invalid'), 'Préparateur(trice) de commandes, CDD saison', 'Transports Exemple (fictif)', 'Casablanca', 'cdd', '🧪 Profil test — Préparation et expédition de commandes dans un entrepôt, pour la période de forte activité. Le poste a été pourvu : merci à toutes les personnes qui ont candidaté. Nous gardons vos coordonnées pour la prochaine saison.', '+212000000004', 'closed', strftime('%Y-%m-%dT%H:%M:%fZ','now','-2880 minutes'), strftime('%Y-%m-%dT%H:%M:%fZ','now','-2880 minutes'));
INSERT INTO pro_jobs (member_id, title, company, city, type, description, contact, status, created_at, updated_at) VALUES ((SELECT id FROM hub_members WHERE email = 'yasmine@demo.ftour.invalid'), 'Assistant(e) événementiel, CDD de 3 mois', 'Atelier Horizon (fictif)', 'Casablanca', 'cdd', '🧪 Profil test — Vous assistez l''équipe sur la préparation et le déroulé d''événements : logistique, accueil des invités, suivi des prestataires. Disponibilité possible en soirée et le week-end. Une première expérience en accueil ou en bénévolat est un vrai plus.', '+212000000001', 'open', strftime('%Y-%m-%dT%H:%M:%fZ','now','-2640 minutes'), strftime('%Y-%m-%dT%H:%M:%fZ','now','-2640 minutes'));
INSERT INTO pro_jobs (member_id, title, company, city, type, description, contact, status, created_at, updated_at) VALUES ((SELECT id FROM hub_members WHERE email = 'reda@demo.ftour.invalid'), 'Livreur partenaire, remplacement d''été', 'Livraisons Exemple (fictif)', 'Casablanca', 'cdd', '🧪 Profil test — Remplacement de deux mois pour des livraisons de colis légers à Casablanca. Véhicule personnel requis. L''offre est désormais fermée, merci de votre intérêt.', '+212000000008', 'closed', strftime('%Y-%m-%dT%H:%M:%fZ','now','-2040 minutes'), strftime('%Y-%m-%dT%H:%M:%fZ','now','-2040 minutes'));
INSERT INTO pro_jobs (member_id, title, company, city, type, description, contact, status, created_at, updated_at) VALUES ((SELECT id FROM hub_members WHERE email = 'karim@demo.ftour.invalid'), 'Refonte d''un site vitrine, mission freelance de 3 semaines', 'Cabinet Exemple Conseil (fictif)', 'Rabat', 'freelance', '🧪 Profil test — Refonte d''un site vitrine d''une dizaine de pages pour une petite structure, avec un hébergement existant. Vous livrez un site simple à maintenir, avec un back-office de base. Budget à discuter selon votre expérience, contact téléphonique en priorité.', '+212000000002', 'open', strftime('%Y-%m-%dT%H:%M:%fZ','now','-1680 minutes'), strftime('%Y-%m-%dT%H:%M:%fZ','now','-1680 minutes'));
